class Solution {
  public java.util.List<java.util.List<Long>> splitPainting(int[][] segments) {
    java.util.TreeMap<Integer, Long> diff = new java.util.TreeMap<>();
    for (int[] s : segments) {
      diff.put(s[0], diff.getOrDefault(s[0], 0L) + s[2]);
      diff.put(s[1], diff.getOrDefault(s[1], 0L) - s[2]);
    }
    java.util.List<java.util.List<Long>> ans = new java.util.ArrayList<>();
    long color = 0;
    Integer prev = null;
    for (java.util.Map.Entry<Integer, Long> e : diff.entrySet()) {
      if (prev != null && color != 0)
        ans.add(java.util.Arrays.asList((long) prev, (long) e.getKey(), color));
      color += e.getValue();
      prev = e.getKey();
    }
    return ans;
  }
}
